def gen(rng):
    def fmt(a, x):
        return f'{len(a)} {x}\n' + ' '.join(map(str, a))
    tests = [fmt([5], 5), fmt([1], 1), fmt([3, 8, 2, 7, 1, 9], 5), fmt([3, 6, 9, 12], 3), fmt([7, 7, 7], 1),
             fmt([2, 2, 2, 2], 4), fmt([1, 2], 10**9), fmt([10**9, 10**9], 10**9), fmt([5, 5, 5, 5, 5], 10)]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            x = rng.randint(1, 12)
            tests.append(fmt([rng.randint(1, 40) for _ in range(n)], x))
    N = 200000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], rng.randint(1, 10**9)))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], 1))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], 1000))
    tests.append(fmt([2 * 10**8 * rng.randint(1, 5) for _ in range(N)], 10**9))
    tests.append(fmt([10**9 - rng.randint(0, 3) for _ in range(N)], 10**9))
    return tests
